package cn.courselens;
import static org.junit.Assert.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class AiChatsTest {
 @Test public void projectsChatsMemoryAndStrengthSurviveReopen()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats store=new AiChats(c);String first=store.project().getString("id"),chat=store.chat().getString("id");store.memory("我更喜欢简洁回答");store.strength(2);store.messages(new JSONArray().put(new JSONObject().put("role","user").put("content","请帮我复习")));store.newProject("英语学习");assertEquals("",store.project().getString("memory"));store.memory("每周复习单词");AiChats reopened=new AiChats(c);assertEquals("英语学习",reopened.project().getString("name"));reopened.select(first,chat);assertEquals(2,reopened.chat().getInt("strength"));assertEquals("我更喜欢简洁回答",reopened.project().getString("memory"));assertEquals("请帮我复习",reopened.chat().getJSONArray("messages").getJSONObject(0).getString("content"));reopened.newChat();assertEquals(0,reopened.chat().getJSONArray("messages").length());assertEquals("我更喜欢简洁回答",reopened.project().getString("memory"));}
 @Test public void temporaryChatsNeverWriteOrReadSavedMemory()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();AiChats saved=new AiChats(c);saved.memory("持久记忆");String before=c.getSharedPreferences("ai_chats",0).getString("state",null);AiChats temp=new AiChats(c,true);assertEquals("",temp.project().getString("memory"));temp.messages(new JSONArray().put(new JSONObject().put("role","user").put("content","私密草稿")));temp.strength(3);temp.memory("临时记忆");assertEquals(before,c.getSharedPreferences("ai_chats",0).getString("state",null));}
 @Test public void malformedSavedDataIsNotReplaced()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("ai_chats",0).edit().putString("state","broken").commit();try{new AiChats(c);fail();}catch(Exception expected){}assertEquals("broken",c.getSharedPreferences("ai_chats",0).getString("state",""));}
}
